# -*- coding: utf-8 -*-
"""Science Stage 7 · Unit 9 Chemical Reactions – Read the lesson (shown below the video) and the lesson document (PDF).
Camday's own text, examples and questions; scope: Cambridge Lower Secondary Science 0893, Stage 7 (7Cc.01–7Cc.03, 7Cp.04, 7SIC.05)."""
from maths_notes_v4.kit4 import H, I, Y, X, K, L, W, BK, Ex, mcq, grid, num

READ = {}
CARD = lambda title, cards, cols=None: dict({"kind": "sciCards", "title": title, "cards": cards}, **({"cols": cols} if cols else {}))

# =====================================================================================================
# 9.1 Physical and chemical changes · 7Cc.01
# =====================================================================================================
READ["9.1"] = L(
    H("Can you undo it?",
      "You can melt chocolate and let it set again. But once you have fried an egg, you can never make it runny again.",
      "What is the difference between these two kinds of change? Write your idea."),
    I("Two kinds of change",
      "Matter can change in two important ways.",
      table=[["", "Physical change", "Chemical change (chemical reaction)"],
             ["new substance made?", "**no**", "**yes**"], ["what changes", "shape, size or state", "the substances themselves – atoms are rearranged"],
             ["easy to reverse?", "usually yes", "usually no"], ["examples", "melting ice, tearing paper, dissolving sugar, boiling water", "burning wood, rusting, cooking an egg, digesting food"]],
      then=["A few chemical changes can be reversed – for example the reaction inside a rechargeable battery when you charge it."]),
    I("The key question",
      "To decide, ask: **has a new substance been made?**",
      table=[["Change", "New substance?", "Kind"], ["salt dissolving in water", "no – evaporate the water and the salt is back", "physical"],
             ["toast browning", "yes – the brown crust is new", "chemical"], ["a glacier melting", "no – still water", "physical"], ["mould growing on fruit", "yes – the mould makes new substances as it feeds", "chemical"]]),
    I("Real life: changes in the kitchen",
      "The kitchen is full of both kinds of change.",
      fig=CARD("Physical or chemical?", [{"t": "Butter melting", "d": "physical – it sets again in the fridge"}, {"t": "Sugar dissolving in tea", "d": "physical – still sugar"},
                                         {"t": "Frying an egg", "d": "chemical – it can never be runny again"}, {"t": "Baking a cake", "d": "chemical – baking powder makes carbon dioxide bubbles"}], 4)),
    Y("Physical or chemical?",
      grid("s7u09r11", "Is each change physical or chemical?", ["Physical", "Chemical"],
           [("a match burning", "Chemical"), ("water freezing into ice", "Physical"), ("milk going sour", "Chemical"), ("chopping wood", "Physical"),
            ("an iron gate rusting", "Chemical"), ("perfume evaporating", "Physical")],
           "Has a new substance been made?", "Burning, souring and rusting make new substances; freezing, chopping and evaporating do not.")),
    X("Dissolving is not a reaction",
      "Students often think dissolving is a chemical change because the solid 'disappears'.",
      "When sugar dissolves, its particles spread out between the water particles – no new substance forms. Evaporate the water and the sugar is still there. Dissolving is a **physical** change."),
    K("Key points",
      "**Physical change**: no new substance; often reversible (melting, dissolving, cutting).",
      "**Chemical change**: new substances made; usually irreversible (burning, rusting, cooking).",
      "Ask: has a new substance been made?"),
    book=BK(
        [("physical change", "a change in which no new substance is made"), ("chemical change", "a change in which new substances are made (a chemical reaction)"),
         ("reversible", "can be changed back")],
        [], [],
        [Ex("Classify as physical or chemical: (a) candle wax melting (b) candle wick burning (c) wood rotting (d) glass breaking.", ans="(a) physical (b) chemical (c) chemical (d) physical"),
         Ex("Give two differences between a physical and a chemical change.", ans="A chemical change makes new substances and is usually irreversible; a physical change makes no new substance and is usually reversible."),
         Ex("Is milk going sour a physical or chemical change? Give a reason.", ans="Chemical – bacteria produce new substances such as lactic acid, and it cannot be reversed."),
         Ex("A student says boiling an egg is a physical change because it is just heating. Explain why she is wrong.",
            ans="The egg white turns into a new solid substance and cannot turn back – that is a chemical change.", think=True)],
        ["tell physical and chemical changes apart", "give examples of each", "explain using the idea of new substances"],
        look=["the comparison table", "changes in the kitchen"],
        note="Read it after the video: physical and chemical changes and how to tell them apart (answers at the back)."),
)

# =====================================================================================================
# 9.2 Simple chemical reactions · 7Cc.03
# =====================================================================================================
READ["9.2"] = L(
    H("Where did the candle go?",
      "A candle burns for an evening and gets shorter and shorter. Has the wax been destroyed?",
      "Think about it, then find out where the atoms go."),
    I("Word equations",
      "A **word equation** sums up a reaction. The **reactants** go on the left, the **products** on the right, and the arrow means 'react to make'.",
      table=[["Reactants", "", "Products"], ["carbon + oxygen", "→", "carbon dioxide"], ["magnesium + oxygen", "→", "magnesium oxide"],
             ["zinc + hydrochloric acid", "→", "zinc chloride + hydrogen"], ["acid + alkali", "→", "salt + water"]],
      then=["We use '+' between substances and never write '=' in a word equation."]),
    Y("Spot the products",
      mcq("s7u09r21", "Copper carbonate is heated and turns into copper oxide and carbon dioxide. What are the products?",
          [("copper oxide and carbon dioxide", True, "Yes – they are made in the reaction."), ("copper carbonate", False, "That is the reactant."),
           ("copper carbonate and heat", False, "Heat is not a substance."), ("copper and oxygen", False, "These are not mentioned as products.")],
          "Products are made; reactants are used up.", "copper carbonate → copper oxide + carbon dioxide.")),
    I("Reactions in the particle model",
      "In a reaction the atoms of the reactants are **rearranged** to make the products.",
      fig={"kind": "sciMatter", "boxes": [{"t": "carbon + oxygen", "d": "reactants", "kind": "mixel", "a": "#D64545", "c": "#37474F"},
                                          {"t": "carbon dioxide", "d": "product", "kind": "compound", "a": "#D64545", "b": "#37474F"}]},
      then=["Energy (for example heat) is needed to start the reaction: it breaks the oxygen molecules apart, then each carbon atom joins with two oxygen atoms to make carbon dioxide.",
            "Sometimes the warmth of the surroundings is enough to start a reaction."]),
    I("Count the atoms",
      "Hydrogen reacts with oxygen to make water: **2 H₂ + O₂ → 2 H₂O**.",
      table=[["", "Hydrogen atoms", "Oxygen atoms"], ["before (2 H₂ + O₂)", "4", "2"], ["after (2 H₂O)", "4", "2"]],
      then=["A reaction only **rearranges** atoms. It cannot create or destroy them, or turn them into other elements. So the **total mass stays the same** – the **conservation of mass**."]),
    I("Predict, watch, explain: does the mass change?",
      "A flask of vinegar on a balance has a balloon of baking soda fixed over its top. The reading is **187.6 g**. The baking soda is tipped in: it fizzes and the balloon fills with carbon dioxide.",
      then=["When the fizzing stops, the balance still reads **187.6 g**. A new substance (carbon dioxide) was made, so this was a chemical reaction – but no atoms were created or destroyed, and the gas was trapped in the balloon."]),
    I("Real data: an open flask",
      "The same reaction in an **open** flask, with no balloon:",
      fig={"kind": "linegraph", "x": {"min": 0, "max": 5, "step": 1, "label": "time (minutes)"}, "y": {"min": 184, "max": 188, "step": 1, "label": "mass (g)"},
           "series": [{"pts": [[0, 187.6], [1, 186.3], [2, 185.6], [3, 185.3], [4, 185.2], [5, 185.2]]}]},
      then=["The mass **falls** by 2.4 g. Does this break the law? No – the carbon dioxide **escaped into the air**. If we could catch it, the total would still be 187.6 g."]),
    W("Using conservation of mass",
      "4.8 g of magnesium burns completely and makes 8.0 g of magnesium oxide. What mass of oxygen joined the magnesium?",
      [("magnesium + oxygen → magnesium oxide", "write the word equation"), ("4.8 + oxygen = 8.0", "mass of reactants = mass of products"), ("oxygen = 8.0 − 4.8 = 3.2 g", "subtract")], "3.2 g"),
    Y("Missing mass",
      num("s7u09r22", "In a sealed flask, 50.0 g of reactants react. What is the total mass of the products (in g)?", 50,
          "Nothing can get in or out of a sealed flask.", "Mass is conserved: 50.0 g.")),
    K("Key points",
      "Word equation: **reactants → products**.",
      "In a reaction atoms are **rearranged**, never created or destroyed.",
      "**Conservation of mass**: total mass of reactants = total mass of products.",
      "If a gas escapes from an open container, the measured mass falls – but no mass is destroyed."),
    book=BK(
        [("word equation", "a summary of a reaction in words: reactants → products"), ("reactant", "a substance used up in a reaction"), ("product", "a new substance made in a reaction"),
         ("conservation of mass", "the total mass stays the same in a reaction")],
        [], [],
        [Ex("Write a word equation: iron reacts with sulfur to make iron sulfide.", ans="iron + sulfur → iron sulfide"),
         Ex("Name the reactants and products: calcium carbonate + hydrochloric acid → calcium chloride + water + carbon dioxide.",
            ans="reactants: calcium carbonate, hydrochloric acid; products: calcium chloride, water, carbon dioxide"),
         Ex("6 g of carbon burns to make 22 g of carbon dioxide. What mass of oxygen was used?", ans="22 − 6 = 16 g"),
         Ex("Marble chips react with acid in an open beaker on a balance. Explain why the reading goes down.", ans="Carbon dioxide gas is made and escapes into the air, so the mass left in the beaker falls."),
         Ex("Draw particle diagrams for 2 H₂ + O₂ → 2 H₂O and use them to explain why mass is conserved.",
            ans="Before and after there are 4 H atoms and 2 O atoms; atoms are only rearranged, so the mass is the same.", think=True)],
        ["write word equations and name reactants and products", "explain reactions using the particle model", "explain and use conservation of mass"],
        look=["counting atoms before and after", "the sealed and open flasks"],
        note="Read it after the video: word equations, particle models and conservation of mass (answers at the back)."),
)

# =====================================================================================================
# 9.3 Useful and harmful reactions · 7SIC.05
# =====================================================================================================
READ["9.3"] = L(
    H("Helpful or harmful?",
      "Burning gas cooks your dinner. Burning coal in a power station gives electricity – and also pollutes the air.",
      "Can the same reaction be both helpful and harmful? Write your view, then read on."),
    I("Useful chemical reactions",
      "We depend on chemical reactions every day.",
      table=[["Reaction", "Word equation (simplified)", "Why it is useful"],
             ["**combustion** (burning)", "fuel + oxygen → carbon dioxide + water (+ energy)", "heat for cooking; energy for vehicles and power stations"],
             ["**photosynthesis**", "carbon dioxide + water → glucose + oxygen (using light)", "makes food and replaces oxygen in the air"],
             ["respiration", "glucose + oxygen → carbon dioxide + water (+ energy)", "releases energy in every living cell"],
             ["making ammonia", "nitrogen + hydrogen → ammonia", "used to make fertilisers so farmers grow more food"],
             ["making plastics", "small molecules from oil or plants join into long chains", "light, cheap, easy-to-shape materials"]]),
    I("Harmful reactions: acid rain",
      "Burning fossil fuels releases **sulfur dioxide** and **nitrogen oxides**. These dissolve in rainwater and make **acid rain**.",
      table=[["Damage", "What happens"], ["stone buildings and statues", "acid reacts with calcium carbonate in marble and limestone: calcium carbonate + sulfuric acid → calcium sulfate + water + carbon dioxide"],
             ["forests", "acids wash minerals out of the soil, so trees weaken and die"], ["lakes", "fish and other animals die if the water becomes too acidic"],
             ["shells and corals", "they are calcium carbonate too, so acids damage them"]],
      then=["Crushed limestone (a base) can be spread on soils and lakes to neutralise the acid. Cleaner power stations remove sulfur dioxide before it escapes."]),
    I("Rusting and how to prevent it",
      "Iron reacts with **oxygen and water** to form **rust** (hydrated iron oxide). Rust is flaky and much weaker than iron, so rusty bridges and cars become dangerous.",
      fig=CARD("Ways to stop rust", [{"t": "Paint", "d": "keeps out air and water"}, {"t": "Oil or grease", "d": "for moving parts such as chains"},
                                     {"t": "Galvanising", "d": "a coat of zinc corrodes instead of the iron"}, {"t": "Stainless steel", "d": "chromium forms a protective surface layer"}], 4)),
    I("Real data: which treatment stops rust best?",
      "Four iron nails were left in damp air for two weeks, then the rust on each was weighed.",
      fig={"kind": "barchart", "labels": ["no treatment", "oiled", "painted", "galvanised"], "values": [36, 14, 6, 1], "ymax": 40, "step": 10, "ylabel": "mass of rust (mg)", "xlabel": "treatment"},
      then=["Every treatment reduced rusting; **galvanising** worked best. Paint and oil work by keeping oxygen and water away from the iron surface."]),
    Y("How much less rust?",
      num("s7u09r31", "Use the chart. How many milligrams less rust formed on the painted nail than on the untreated nail?", 30, "Subtract the painted value from the untreated value.",
          "36 − 6 = 30 mg.", errs=[(42, "Subtract, do not add.")])),
    Y("Why does paint work?",
      mcq("s7u09r32", "Why does painting a steel bridge slow down rusting?",
          [("It keeps oxygen and water away from the iron.", True, "Yes – iron needs both to rust."), ("Paint reacts with rust and removes it.", False, "Paint only covers the surface."),
           ("Paint makes the iron stronger.", False, "It does not change the strength of the iron."), ("Paint is an alkali.", False, "Paint works as a barrier, not by neutralising.")],
          "What does iron need in order to rust?", "Paint is a barrier between the iron and the air and water.")),
    K("Key points",
      "Useful reactions: combustion, photosynthesis, respiration, making fertilisers and plastics.",
      "Burning fossil fuels causes **acid rain**, which damages buildings, forests and lakes.",
      "**Rusting** needs oxygen and water; prevent it with paint, oil, zinc (galvanising) or stainless steel."),
    book=BK(
        [("combustion", "burning: a reaction with oxygen that releases energy"), ("acid rain", "rain made acidic by sulfur dioxide and nitrogen oxides"),
         ("galvanising", "coating iron with zinc to stop it rusting"), ("rust", "hydrated iron oxide, formed when iron reacts with oxygen and water")],
        [], [],
        [Ex("Give two useful chemical reactions and say why each is useful.", ans="for example: combustion – heat for cooking; photosynthesis – food and oxygen; making ammonia – fertilisers"),
         Ex("Explain how burning coal can damage a marble statue many kilometres away.", ans="Burning coal releases sulfur dioxide, which dissolves in rain to form acid rain; the acid reacts with the calcium carbonate in the marble."),
         Ex("Suggest the best way to protect: (a) a bicycle chain (b) a metal fence (c) a bucket.", ans="(a) oil (b) paint (c) galvanising"),
         Ex("In the nail experiment, name the independent variable and the dependent variable, and give one control variable.",
            ans="independent: type of treatment; dependent: mass of rust; control: e.g. size of nail, time, how damp the air is", think=True)],
        ["describe useful chemical reactions", "describe how acid rain forms and the damage it does", "explain how to prevent rusting"],
        look=["the table of useful reactions", "the rust treatment chart"],
        note="Read it after the video: useful reactions, acid rain, rusting and rust prevention (answers at the back)."),
)

# =====================================================================================================
# 9.4 Has a reaction taken place? · 7Cc.01, 7Cc.02, 7Cp.04
# =====================================================================================================
READ["9.4"] = L(
    H("Detective work",
      "Drop a vitamin tablet into water and it fizzes. Leave a cut apple in the air and it goes brown. Mix two clear liquids and a cloud appears.",
      "What clues tell you a new substance has been made?"),
    I("Signs of a chemical reaction",
      "We cannot see atoms rearranging, but we can see the evidence.",
      fig=CARD("Look for …", [{"t": "a colour change", "d": "green powder turns black"}, {"t": "a precipitate", "d": "a solid appears in a solution"},
                              {"t": "a gas (fizzing)", "d": "bubbles: effervescence"}, {"t": "reactants used up", "d": "a metal ribbon disappears"},
                              {"t": "an energy change", "d": "gets hot or cold, or gives out light"}], 5)),
    I("Predict, watch, explain: heating copper carbonate",
      "Green copper carbonate powder is heated strongly. The gas given off is bubbled through limewater.",
      then=["The green powder turns **black** and the limewater turns **milky**. Two signs of a reaction: a colour change and a gas.",
            "**copper carbonate → copper oxide + carbon dioxide**. The black solid is copper oxide; the gas is carbon dioxide."]),
    I("Colour changes and precipitates",
      "An iron nail in blue copper sulfate solution becomes coated with reddish-brown copper, and the solution fades to pale green: **iron + copper sulfate → iron sulfate + copper**.",
      then=["Mix two clear solutions – silver nitrate and sodium chloride – and a white solid appears at once. Silver chloride is **insoluble**, so it separates out as a **precipitate**."]),
    I("Testing for gases",
      "Three common gases each have their own test.",
      table=[["Gas", "Test", "Positive result", "One way to make it"],
             ["**hydrogen**", "lighted splint at the mouth of the tube", "**squeaky pop**", "magnesium + dilute acid"],
             ["**carbon dioxide**", "bubble through limewater", "limewater turns **milky**", "carbonate + acid (vinegar + baking soda)"],
             ["**oxygen**", "put in a **glowing** splint", "splint **relights**", "hydrogen peroxide breaking down; photosynthesis"]]),
    Y("Identify the gas",
      grid("s7u09r41", "Which gas gives each result?", ["Hydrogen", "Carbon dioxide", "Oxygen"],
           [("relights a glowing splint", "Oxygen"), ("turns limewater milky", "Carbon dioxide"), ("squeaky pop with a lighted splint", "Hydrogen")],
           "Three gases, three tests.", "Relights → oxygen; milky limewater → carbon dioxide; squeaky pop → hydrogen.")),
    I("Where do the reactants go?",
      "Magnesium ribbon in dilute hydrochloric acid fizzes and slowly disappears. The magnesium atoms have not stopped existing.",
      then=["They are now part of the product **magnesium chloride**, which is dissolved in the solution: **magnesium + hydrochloric acid → magnesium chloride + hydrogen**. Evaporate the water and the white solid appears."]),
    Y("Is it a reaction?",
      mcq("s7u09r42", "Which observation is the best evidence that a chemical reaction has happened?",
          [("Two clear solutions mix and a yellow solid appears.", True, "Yes – a precipitate is a new substance."), ("Ice melts in a glass.", False, "Melting is a physical change."),
           ("Salt dissolves in water.", False, "Dissolving is a physical change."), ("Water boils and bubbles.", False, "The bubbles are water vapour – a change of state.")],
          "Look for a new substance.", "A precipitate forming from two solutions shows a new, insoluble substance.")),
    K("Key points",
      "Signs of a reaction: **colour change, precipitate, gas (effervescence), reactants used up**, energy change.",
      "Gas tests: hydrogen – squeaky pop; carbon dioxide – limewater milky; oxygen – relights a glowing splint.",
      "Reactants that 'disappear' have become part of the products."),
    book=BK(
        [("precipitate", "an insoluble solid that forms when two solutions react"), ("effervescence", "fizzing: bubbles of gas given off in a reaction"),
         ("insoluble", "does not dissolve")],
        [], [],
        [Ex("List four signs that a chemical reaction has taken place.", ans="colour change; precipitate forms; gas given off; reactants used up (or temperature change)"),
         Ex("Describe the test and result for: (a) oxygen (b) carbon dioxide (c) hydrogen.", ans="(a) glowing splint relights (b) limewater turns milky (c) lighted splint – squeaky pop"),
         Ex("A nail is left in copper sulfate solution. Give two observations that show a reaction.", ans="a red-brown coating forms on the nail; the blue solution turns pale green"),
         Ex("Quick quiz.", ("Is burning paper a physical or chemical change?", "chemical"), ("What are the products when an acid reacts with a carbonate?", "a salt, water and carbon dioxide"),
            ("Why does a balance reading fall when a gas is made in an open flask?", "the gas escapes into the air"), ("How do you test for oxygen?", "a glowing splint relights")),
         Ex("When magnesium reacts with acid, the ribbon disappears. A student says the magnesium has been destroyed. Explain why she is wrong.",
            ans="The magnesium atoms are now in magnesium chloride, dissolved in the solution; atoms are never destroyed.", think=True)],
        ["recognise the signs of a chemical reaction", "describe the tests for hydrogen, carbon dioxide and oxygen", "explain where the reactants go"],
        look=["the signs of a reaction", "the three gas tests"],
        note="Read it after the video: signs of reactions, precipitates, gas tests and a quick quiz (answers at the back)."),
)
